# tools/verify-generated.sh - Verify generated code is up-to-date
#
# Usage:
#   tools/verify-generated.sh <project.mus>
#
# Exit codes:
#   0 - Generated code is up-to-date
#   1 - Generated code is stale or muscomp not found
#   2 - Invalid arguments or missing files

set -euo pipefail

REPO_ROOT=$(cd "$(dirname "$0")/.." && pwd)
MUSCOMP="${MUSCOMP_BIN:-$REPO_ROOT/toolchain/muscomp/build/Debug/muscomp}"

# Parse arguments
if [[ $# -eq 0 ]]; then
    echo "Error: No project file specified." >&2
    echo "Usage: tools/verify-generated.sh <project.mus>" >&2
    exit 2
fi

PROJECT_FILE="$1"

# Validate project file exists
if [[ ! -f "$PROJECT_FILE" ]]; then
    echo "Error: Project file not found: $PROJECT_FILE" >&2
    exit 2
fi

# Verify muscomp exists
if [[ ! -x "$MUSCOMP" ]]; then
    echo "Error: muscomp not found at $MUSCOMP" >&2
    echo "Build with: cd toolchain/muscomp && cmake --preset debug && cmake --build --preset debug" >&2
    exit 1
fi

# Run lint-only mode to verify generated code without modifying the working tree
# --lint-only performs full validation and reports drift without regenerating
echo "Verifying generated code for $PROJECT_FILE..."
if "$MUSCOMP" --lint-only --project "$PROJECT_FILE" --validate-output; then
    echo "Generated code is up-to-date."
    exit 0
else
    echo "Error: Generated code is stale or invalid. Run muscomp to regenerate." >&2
    exit 1
fi
